\mathcal C_{\mathrm{hom}}:\quad&
\left(
\begin{gathered}
\mathrm{A0\_FAIL},\ \mathrm{A1\_PASS\_ANALYTIC},\\
\mathrm{A2\_FAIL},\ \mathrm{A3\_FAIL},\ \mathrm{A4\_FAIL}
\end{gathered}
\right),\\[-1pt]
&\texttt{ROUTE\_A\_REJECTED}.
